import { readFile } from 'node:fs/promises'
import { bearerToken, createOmnaraClient, openAgentEventStream, sdk } from '@omnara/sdk'
const client = createOmnaraClient({ auth: bearerToken(process.env.OMNARA_TOKEN!) })
const path = { orgID: 'org_...', projectID: 'proj_...' }
const config = await sdk.createAgentConfig({
client,
path,
body: { source: await readFile('agent.yaml', 'utf8'), source_format: 'yaml' },
})
const launched = await sdk.createAgent({
client,
path,
body: { config: config.data.id, message: "Report this machine's free disk space." },
})
const agentID = launched.data.agent.id
for await (const event of openAgentEventStream({ client, path: { ...path, agentID } })) {
console.log(event)
}

struct RenderState {
cache: HashMap<String, Arc<String>>,
template: String,
}
fn render_page(state: &mut RenderState, name: &str) -> Arc<String> {
// Mutably borrow `state.cache` using the Entry API.
let entry = state.cache.entry(name.to_string());
entry.or_insert_with(|| {
// Create the entry if it doesn't exist.
Arc::new(state.template.replace("$name", name))
}).clone()
}

fn render_page(state: &Mutex<RenderState>, name: &str) -> Arc<String> {
let state: MutexGuard <' _ , RenderState> = state.lock().unwrap();
// The borrow checker complains that "state" is mutably borrowed here:
let entry = state.cache.entry(name.to_string());
entry.or_insert_with(|| {
// ... but then used here while it is still borrowed:
Arc::new(state.template.replace("$name", name))
}).clone()
}

